    // ignoreProps: true mirrors range-mfe — eslint-plugin-react@7.37.x does
    // not support per-attribute filtering, so placeholder=/aria-label=/title=
    // literals are guarded via code review + the i18n-gate data-array grep.
    'react/jsx-no-literals': ['error', {
      noStrings: true,
      // Decorative aria-hidden glyphs only — never user-facing copy (those
      // go through m.range_kite_*()). Mirrors range-mfe's allowlist + the X-clone
      // icon set: reply ↩, repost ↻, quote ✎, like ♥/♡, views ▤, nav ⌂/○,
      // close ✕.
      allowedStrings: ['.', ',', '—', ':', '(', ')', '/', '|', '•', '·', '*', '%', '✓', '✕', '⚠', '→', '←', '↑', '↓', '▸', '▾', '└', '_', '@', ' at ', '↩', '↻', '✎', '♥', '♡', '▤', '⌂', '○'],
