import type { Config } from "tailwindcss";
import cogPreset from "../ui/tailwind.preset";

// CogOS 3.0 design system — the cog-* token theme now lives in the shared
// preset (frontends/ui/tailwind.preset.ts), the single source of truth
// consumed by every MFE. See docs/design/design.md §17 for the spec.
// Authors MUST NOT inline raw `slate-*` / `gray-*` / hex values in JSX.
//
// kite-mfe now adopts the preset like every other MFE. It previously forked
// 7 `cog-*` keys locally — including an invented `cog-blue-500 = #2C66EC`
// that matches no spec, past or present — to shield two already-shipped
// surfaces (LoginRoute's submit button, FeedPanel's active-tab underline)
// from the preset's "Indigo Atlas" cog-blue refresh (cog-blue-600
// #1A4FD6 → #2742C9). That fork is retired: shared `cog-*` names are never
// redefined locally (see docs/design/design.md's standardization ruling).
//
// The four shipped surfaces that rendered the old blue (LoginRoute,
// FeedPanel, plus platform-chrome/src/kite/{VerifiedBadge,kiteButtonClasses}
// which this MFE's `content` glob also compiles) now ALL render Indigo
// Atlas, deliberately uniformly: the latter two live outside this MFE's
// ownership and already render Indigo Atlas today in range-mfe's Kite
// simulation (range-mfe adopted the preset earlier), so preserving the old
// blue on only 2 of the 4 co-visible surfaces (they appear together in the
// same feed timeline) would read as a broken, half-migrated app rather than
// a coherent brand choice. See src/styles/index.css and the colour-change
// table in the PR description for the exact before/after values.
//
// kite-mfe's genuine brand identity — the parts of the X-clone simulation
// that are NOT part of the cog-* system — stays scoped under `kite-*`
// tokens, mirroring the documented fork range-mfe maintains for its own
// Kite simulation (range-mfe/tailwind.config.ts). `kite-like` (the filled
// heart, #1876/#1874) is the one token that fork needs today.
export default {
  presets: [cogPreset],
  content: [
    "./index.html",
    "./src/**/*.{ts,tsx}",
    // platform-chrome is consumed at source via pnpm workspace symlink.
    "../platform-chrome/src/**/*.{ts,tsx}",
    // Paraglide emits one .js AND one .d.ts per message key — 12,536 files,
    // 6,268 of them matching the `*.ts` glob above, none containing a single
    // class name. Tailwind's JIT scanner walked all of them on every build.
    // Excluding them emits byte-identical CSS and removes that scan work from
    // every MFE's build. Build time is not measured per MFE; the one
    // measurement taken was ask-mfe, 211s to 117s (Node 20, local).
    "!../platform-chrome/src/paraglide/generated/**",
    // @omnicore-platform/ui primitives are source-inlined — scan them so
    // their cog-* utility classes are emitted into this MFE's bundle.
    "../ui/src/**/*.{ts,tsx}",
  ],
  darkMode: ["class", '[data-theme="dark"]'],
  theme: {
    extend: {
      colors: {
        // Like-state heart (fold complete, #1876) — see file-header note.
        "kite-like": "rgb(var(--kite-like) / <alpha-value>)",
      },
    },
  },
  plugins: [],
} satisfies Config;


