import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import federation from "@originjs/vite-plugin-federation";
import { paraglideVitePlugin } from "@inlang/paraglide-js";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import { resolve, dirname } from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// VITE_BASE_PATH is set at build time when kite-mfe is served from a
// non-root path (e.g. https://host/k/). Vite emits all asset URLs with
// this prefix so chunks resolve when Traefik routes /k/* to this
// container without stripping the prefix. Default "/" preserves dev
// behavior on http://localhost:5181.
//
// IMPORTANT: kite-mfe is a PARTICIPANT app served OUTSIDE the Keycloak-gated
// shell-mfe. It has its own index.html + router with NO OIDC guard. Auth
// is the `kite_session` httpOnly cookie minted by range-bff; the app
// bootstraps via GET /api/v1/kite/me and redirects to /k/login on 401.
const basePath = process.env.VITE_BASE_PATH ?? "/";

// In e2e builds (VITE_E2E=1) we force import.meta.env.DEV=true so the
// pseudolocale transform and leak-observer registry remain active in the
// built bundle, matching range-mfe's e2e build behavior.
const e2eMode = process.env.VITE_E2E === "1";

export default defineConfig({
  define: e2eMode
    ? {
        "import.meta.env.DEV": true,
        "import.meta.env.VITE_E2E": JSON.stringify("1"),
      }
    : undefined,
  base: basePath,
  plugins: [
    react(),
    // Disabled under vitest (process.env.VITEST): a short-lived test process
    // boots this config and kicks off a recompile that gets interrupted
    // mid-write, leaving the SHARED committed generated dir partial (index
    // referencing per-message files that were never written) → the app
    // white-screens with 404s. Tests get the compiled output from the
    // paraglide-global-setup globalSetup (runs once, to completion) instead.
    ...(process.env.VITEST
      ? []
      : [
          paraglideVitePlugin({
            project: "../../frontends/project.inlang",
            outdir: "../../frontends/platform-chrome/src/paraglide/generated",
            strategy: ["globalVariable", "baseLocale"],
            emitGitIgnore: false,
            emitPrettierIgnore: false,
            emitReadme: false,
            emitTsDeclarations: true,
          }),
        ]),
    federation({
      name: "kite",
      filename: "remoteEntry.js",
      exposes: {
        "./KiteApp": "./src/KiteApp.tsx",
      },
      shared: ["react", "react-dom", "react-router-dom"],
    }),
    // Vite's default CSS handler intercepts *.css imports before the ?raw
    // suffix can return raw text in the Vitest jsdom environment (Vitest
    // stubs CSS to an empty module by default). This plugin bypasses that
    // for kiteLikeToken.test.ts's config-content assertions — mirrors
    // frontends/ui/vite.config.ts's identical "raw-css-for-tests" plugin.
    {
      name: "raw-css-for-tests",
      enforce: "pre",
      resolveId(id: string, importer?: string) {
        if (id.endsWith(".css?raw")) {
          const cleanId = id.replace(/\?raw$/, "");
          const base = importer ? dirname(importer) : __dirname;
          const abs = resolve(base, cleanId);
          const encoded = Buffer.from(abs).toString("base64url");
          return `\0rawcss/${encoded}.txt`;
        }
        return undefined;
      },
      load(id: string) {
        if (id.startsWith("\0rawcss/") && id.endsWith(".txt")) {
          const encoded = id.slice("\0rawcss/".length, -".txt".length);
          const filePath = Buffer.from(encoded, "base64url").toString("utf-8");
          try {
            const content = readFileSync(filePath, "utf-8");
            return `export default ${JSON.stringify(content)}`;
          } catch {
            return `export default ""`;
          }
        }
        return undefined;
      },
    },
  ],
  server: {
    port: 5181,
    proxy: {
      // kite-mfe in dev mode is on :5181; range-bff on :8087.
      "/api": {
        target: "http://localhost:8087",
        changeOrigin: false,
      },
    },
  },
  // preview is used by `make kite-mfe-dev-federated`: vite's dev server can't
  // serve a Module Federation remoteEntry.js, so dev:federated runs
  // `vite build --watch` + `vite preview` on 5181 — the same host port the
  // kite-mfe container binds, so the Makefile target stops that container
  // first. CORS allows the shell host origin (:5173) and the
  // range-standalone-federated dev origin (:5177), matching commons-mfe, so a
  // cross-origin remoteEntry fetch is not blocked once something consumes
  // `kite/KiteApp`. The /api proxy is repeated from `server` because preview
  // does not inherit it, and kite-mfe's `kite_session` cookie requires the app
  // and its /api/v1/kite/* calls to stay same-origin.
  preview: {
    port: 5181,
    strictPort: true,
    cors: { origin: ["http://localhost:5173", "http://localhost:5177"] },
    proxy: {
      "/api": {
        target: "http://localhost:8087",
        changeOrigin: false,
      },
    },
  },
  build: {
    target: "esnext",
    minify: "esbuild", // MF works minified (verified on admin-mfe); the unminified ~15MB chunk blows the e2e remote-mount budget under CI runner contention
    cssCodeSplit: false,
  },
  test: {
    environment: "jsdom",
    globals: true,
    setupFiles: ["./tests/setup.ts"],
    globalSetup: ["../platform-chrome/tests/paraglide-global-setup.ts"],
    css: {
      // Allow CSS imports to reach the raw-css-for-tests plugin above rather
      // than being stubbed by Vitest. The plugin intercepts *.css?raw before
      // postcss sees them.
      include: /\.css(\?raw)?$/,
    },
    // Fork workers can OOM ("JavaScript heap out of memory") on CI's
    // ubuntu-24.04 runners once the suite + coverage instrumentation heap
    // grows. Raises the per-worker V8 heap ceiling to 8192 MB — GitHub
    // ubuntu runners have 16 GB. Deliberately top-level `execArgv`, NOT
    // nested under `poolOptions.forks` the way range-mfe's vite.config.ts
    // still has it: Vitest 4's pool-rework REMOVED `test.poolOptions` — that
    // shape is now a silently-inert deprecated no-op (verified empirically:
    // the forked worker's own process.execArgv does not contain the flag
    // when nested that way). Also deliberately does not cap fork count — a
    // fork-count cap tried on a heavy suite elsewhere in this repo regressed
    // it by serializing the suite onto fewer reused forks, letting heap
    // accumulate across the run until an OOM; leave fork count at its
    // default.
    execArgv: ["--max-old-space-size=8192"],
    coverage: {
      provider: "v8",
      all: true,
      include: ["src/**/*.{ts,tsx}"],
      reporter: ["text", "json-summary", "lcov"],
      reportsDirectory: "./coverage",
      exclude: [
        "node_modules/**",
        "dist/**",
        "tests/**",
        "**/*.config.*",
        "**/*.d.ts",
        "**/*.stories.*",
        "src/main.tsx",
      ],
      thresholds: {
        // Bare (non-glob) keys + perFile: true — every MFE in this repo uses
        // this exact shape so the gate is uniform across all 15 configs.
        // Bare keys (not a `"**"` glob group) are required so a shard job's
        // CLI override (`--coverage.thresholds.lines=0` etc., in
        // frontend-test.yml) can reach and neutralize them — a CLI override
        // only reaches bare keys, never a glob-keyed threshold group.
        // perFile applies the 80% floor to each individual file rather than
        // reducing across the whole report to one project-wide aggregate.
        perFile: true,
        lines: 80,
        branches: 80,
        functions: 80,
        statements: 80,
      },
    },
  },
});



